mkdir -p /workspace/probe/tuitest/src && cd /workspace/probe/tuitest && cat > Cargo.toml <<'EOF'
[package]
name = "tuitest"
version = "0.1.0"
edition = "2021"

[dependencies]
tui = "0.19"
crossterm = "0.25"
EOF
cat > src/main.rs <<'EOF'
use crossterm::{execute, terminal::{enable_raw_mode, EnterAlternateScreen}};
use std::io::stdout;
use tui::{backend::CrosstermBackend, Terminal, widgets::{Block, Borders, Paragraph}, text::{Span, Spans}, style::{Style, Modifier}, layout::{Layout, Direction, Constraint}};

fn main() {
    enable_raw_mode().unwrap();
    let mut out = stdout();
    execute!(out, EnterAlternateScreen).unwrap();
    let backend = CrosstermBackend::new(out);
    let mut term = Terminal::new(backend).unwrap();
    term.clear().unwrap();
    term.draw(|f| {
        let chunks = Layout::default().direction(Direction::Vertical)
            .constraints([Constraint::Length(3), Constraint::Min(1)].as_ref())
            .split(f.size());
        let title = Paragraph::new(Spans::from(vec![
            Span::styled("ngrrram!", Style::default().add_modifier(Modifier::BOLD)),
            Span::raw("   by winterveil"),
        ])).block(Block::default().borders(Borders::ALL));
        f.render_widget(title, chunks[0]);
        let p = Paragraph::new(Spans::from(vec![
            Span::styled("at nt at nt at nt ", Style::default().add_modifier(Modifier::BOLD)),
        ]));
        f.render_widget(p, chunks[1]);
    }).unwrap();
    std::io::Write::flush(&mut std::io::stdout()).unwrap();
}
EOF
cargo build 2>&1 | tail -3

