#!/usr/bin/env python3
"""Interactive driver: spawn ./executable in pty, run scripted actions.
Actions can reference screen content (e.g. type the lesson text)."""
import os, pty, sys, time, select, fcntl, termios, struct, argparse, importlib.util

spec = importlib.util.spec_from_file_location('term', os.path.join(os.path.dirname(__file__), 'term.py'))
termmod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(termmod)

class Session:
    def __init__(self, args, rows=24, cols=80):
        self.rows, self.cols = rows, cols
        self.pid, self.fd = pty.fork()
        if self.pid == 0:
            os.environ['TERM'] = 'xterm-256color'
            os.execv('./executable', ['./executable'] + args)
            os._exit(127)
        fcntl.ioctl(self.fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
        self.out = b''
        self.mark = 0  # offset since last frame extraction

    def drain(self, timeout):
        end = time.time() + timeout
        while time.time() < end:
            r, _, _ = select.select([self.fd], [], [], max(0, end - time.time()))
            if self.fd in r:
                try:
                    chunk = os.read(self.fd, 65536)
                except OSError:
                    return False
                if not chunk:
                    return False
                self.out += chunk
        return True

    def send(self, data: bytes, settle=0.4):
        os.write(self.fd, data)
        self.drain(settle)

    def screen(self):
        t, _ = termmod.emulate(self.out, self.rows, self.cols)
        return t.text()

    def screen_since_mark(self):
        t, _ = termmod.emulate(self.out[self.mark:], self.rows, self.cols)
        return t.text(), t.attrdump()

    def close(self):
        try:
            os.write(self.fd, b'\x1b')
            self.drain(0.5)
        except OSError:
            pass
        try:
            os.close(self.fd)
        except OSError:
            pass
        try:
            os.waitpid(self.pid, 0)
        except ChildProcessError:
            pass

